#include "platform/native_topology_asset_census.h"
#include "platform/native_sha256.h"
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define CHECK(x) do { if (!(x)) { fprintf(stderr,"failed %s:%d: %s\n",__FILE__,__LINE__,#x); return 1; } } while (0)
#define SECTOR 2352u
static void W16(uint8_t *p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);} static void W32(uint8_t *p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}
static uint8_t *User(uint8_t *d,unsigned lba){return d+(size_t)lba*SECTOR+24;}
static void Headers(uint8_t *d,size_t n){for(size_t i=0;i<n/SECTOR;i++){uint8_t *p=d+i*SECTOR;p[0]=0;memset(p+1,0xff,10);p[11]=0;p[15]=2;}}
static void Hash(const uint8_t *p,size_t n,uint8_t d[32]){struct NativeSha256 h;NativeSha256_Init(&h);NativeSha256_Update(&h,p,n);NativeSha256_Final(&h,d);}
static void Entry(uint8_t *b,unsigned i,unsigned off,unsigned size){W32(b+8+i*8,off);W32(b+12+i*8,size);}
static void Build(uint8_t *d,size_t n){uint8_t *p,*big,*lev,*ptr;memset(d,0,n);Headers(d,n);p=User(d,16);p[0]=1;memcpy(p+1,"CD001",5);p[6]=1;W32(p+158,20);W32(p+166,2048);p=User(d,20);p[0]=47;W32(p+2,21);W32(p+10,2048);p[25]=0;p[32]=13;memcpy(p+33,"BIGFILE.BIG;1",13);big=User(d,21);W32(big+4,195);Entry(big,1,1,0x300);Entry(big,2,2,24);lev=User(d,22);W32(lev+0,0x1c0);W32(lev+0x148,1);W32(lev+0x14c,0x240);W32(lev+0x188,0x260);W32(lev+0x1c0,1);W32(lev+0x1cc,0x1e0);lev[0x1e0+0x3e]=0;W16(lev+0x240+8,0xffff);W16(lev+0x240+9,0xffff);W16(lev+0x240+10,0xffff);W16(lev+0x240+11,0xffff);W32(lev+0x260,0x270);W16(lev+0x270,(uint16_t)-0x1303);W16(lev+0x272,1);ptr=User(d,23);W32(ptr,20);W32(ptr+4,0);W32(ptr+8,0x14c);W32(ptr+12,0x188);W32(ptr+16,0x1cc);W32(ptr+20,0x260);}
int main(void){uint8_t disc[24*SECTOR],hash[32],json[16384],before[16384];struct NativeTopologyAssetCensus c;size_t n1,n2;Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));CHECK(c.corpusCount==25&&c.storedCount==1&&c.selectorAddressableCount==1&&c.excludedStoredEntryCount==0);CHECK(c.records[0].restartAvailable&&c.records[0].navAvailableMask==1&&c.records[0].topology.levelID==0);CHECK(NativeTopologyAssetCensus_ToJson(&c,(char *)json,sizeof(json),&n1));CHECK(NativeTopologyAssetCensus_ToJson(&c,(char *)before,sizeof(before),&n2)&&n1==n2&&!memcmp(json,before,n1));CHECK(!NativeTopologyAssetCensus_ToJson(&c,(char *)before,n1-1,&n2));
	/* Synthetic-only negative corpus: bad hash/raw sync, PVD, directory, BIG
	 * count/extent, relocation slot, null nav, and poison NavHeader.last. */
	hash[0]^=1;CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));hash[0]^=1;disc[16*SECTOR+1]=0;CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);disc[20*SECTOR+24]=1;CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);W32(User(disc,21)+4,4097);CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));Build(disc,sizeof(disc));Hash(disc,sizeof(disc),hash);W32(User(disc,21)+8+1*8,99);CHECK(!NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c));
	Build(disc,sizeof(disc));W32(User(disc,23)+4,0x14c);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].stored&&!c.records[0].selectorAddressable);Build(disc,sizeof(disc));W32(User(disc,22)+0x260,0);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].selectorAddressable&&c.records[0].navAvailableMask==0);Build(disc,sizeof(disc));W32(User(disc,22)+0x148,0);User(disc,22)[0x1e0+0x3e]=0xff;Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].selectorAddressable&&!c.records[0].restartAvailable);Build(disc,sizeof(disc));User(disc,22)[0x1e0+0x3e]=0xff;Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].selectorAddressable);Build(disc,sizeof(disc));W32(User(disc,22)+0x278,0xdeadbeef);Hash(disc,sizeof(disc),hash);CHECK(NativeTopologyAssetCensus_FromRawMode2(disc,sizeof(disc),hash,&c)&&c.records[0].selectorAddressable);return 0;}
